"Alex Ferguson era famoso por el «secador de pelo»: broncas a gritos a centímetros de la cara del jugador.":"Alex Ferguson era famoso per l'«hairdryer treatment»: sfuriate urlate a pochi centimetri dalla faccia del giocatore.",
"Alex Ferguson llegó al Manchester United en noviembre de 1986 y no ganó su primer título hasta la FA Cup de 1990. El club le mantuvo pese a las críticas y acabó ganando trece ligas.":"Alex Ferguson arrivò al Manchester United nel novembre 1986 e non vinse il suo primo titolo fino alla FA Cup del 1990. Il club lo confermò nonostante le critiche e finì per vincere tredici campionati.",
