"Cada cambio es un golpe de energía. Sois un equipo de 22.":"Ogni cambio è una scarica di energia. Siete una squadra di 22.",
"Cada desventaja tiene su ventaja. Con menos dinero, tenemos más hambre. Y el hambre gana más partidos que el oro.":"Ogni svantaggio ha il suo vantaggio. Con meno soldi abbiamo più fame. E la fame vince più partite dell'oro.",
"Cada día se nota más lo que vale {name}. Otro gol y van {goals}. ¡CRACK!":"Ogni giorno si vede di più quanto vale {name}. Un altro gol e sono {goals}. FENOMENO!",
"Cada día un reto. Pero sufrir es parte del trabajo. Quien no sufre no sabe lo que vale volver a jugar.":"Ogni giorno una sfida. Ma soffrire fa parte del lavoro. Chi non soffre non sa quanto vale tornare a giocare.",
"Cada etapa de tu mascota tiene su propio dibujo: cuando crezca, quizá tengas que volver a colocarlos.":"Ogni fase del tuo animale ha il suo disegno: quando crescerà, potresti doverli riposizionare.",
"Cada jugador rinde al 100 % en su posición.":"Ogni giocatore rende al 100% nel suo ruolo.",
"Cada mal partido se compara con las leyendas. La presión se nota.":"Ogni partita storta viene paragonata alle leggende. La pressione si sente.",
"Cada ojeador te trae informes al empezar cada tramo. Con más estrellas, el potencial que ves es más fiable; con más viajes, encuentra más jugadores.":"Ogni osservatore ti porta rapporti all'inizio di ogni fase. Con più stelle, il potenziale che vedi è più affidabile; con più viaggi, trova più giocatori.",
"Cada partido es historia. Los jóvenes aprenden de ti.":"Ogni partita è storia. I giovani imparano da te.",
"Cada partido peor que el anterior. ¿Qué estamos haciendo?":"Ogni partita peggio della precedente. Cosa stiamo facendo?",
