"Con un baile que mis sobrinos me enseñaron. Han visto el vídeo en redes, y me han dicho que ni de lejos.":"Con un balletto che mi hanno insegnato i miei nipoti. Hanno visto il video sui social, e mi hanno detto che non ci siamo proprio.",
