"Con un segundo de 3 estrellas sabrás su punto débil.":"Con un vice da 3 stelle conoscerai il suo punto debole.",
"Con una sangre fría increíble, sales jugando y arrancas la contra.":"Con una freddezza incredibile, esci palleggiando e fai partire il contropiede.",
"Con {age} años, cada pretemporada cuesta un poco más. Tu preparador te propone un plan estricto.":"A {age} anni, ogni ritiro costa un po' di più. Il tuo preparatore ti propone un piano rigoroso.",
