"Cuando las gaviotas siguen al barco pesquero es porque creen que les van a tirar sardinas. Muchas gracias.":"Quando i gabbiani seguono il peschereccio è perché pensano che verranno gettate sardine in mare. Grazie mille.",
"Cuando tu equipo juega mal pero ganas: 'Eso es lo importante' / Cuando tu equipo juega bien pero pierdes: 😭":"Quando la tua squadra gioca male ma vince: 'È questo che conta' / Quando gioca bene ma perde: 😭",
"Cuando uno pierde, todos pierden. Hoy el único responsable soy yo. Yo debí dar más.":"Quando uno perde, perdono tutti. Oggi l'unico responsabile sono io. Dovevo dare di più.",
