"El VAR es un invento maravilloso. Lástima que lo manejen humanos, que al final son los que se equivocan.":"Il VAR è un'invenzione meravigliosa. Peccato che lo usino gli esseri umani, che alla fine sono quelli che sbagliano.",
"El VAR ha intervenido varias veces hoy. ¿Opina que mejora el fútbol?":"Il VAR è intervenuto più volte oggi. Pensi che migliori il calcio?",
"El VAR lo ve todo: gol anulado y amarilla.":"Il VAR vede tutto: gol annullato e giallo.",
