"El agente cumple su amenaza y tres jugadores se ponen tensos.":"L'agente mantiene la minaccia e tre giocatori si innervosiscono.",
"El agente de {name} representa también a otros dos de tus jugadores. Ahora exige que su cliente cobre como los mejores, o «se lo pensarán todos».":"L'agente di {name} rappresenta anche altri due tuoi giocatori. Ora pretende che il suo assistito guadagni come i migliori, o «ci penseranno tutti».",
"El agente recula: su cliente no quiere irse. Ganas autoridad.":"L'agente fa marcia indietro: il suo assistito non vuole andarsene. Guadagni autorità.",
"El algoritmo recomienda jugadores que ya no existen o están retirados. Hazmerreír.":"L'algoritmo consiglia giocatori che non esistono più o sono ritirati. Zimbello di tutti.",
"El ambiente se enrarece y alguno lo comenta en redes.":"L'ambiente si guasta e qualcuno ne parla sui social.",
"El ambiente se enrarece.":"L'aria si fa pesante.",
"El analista se queda con cara de pocos amigos.":"L'analista ti guarda storto.",
"El analista te deja un informe de cuarenta páginas sobre el jugador que tendrás enfrente en el partido contra el {opp}. Es tarde y mañana hay sesión temprano.":"L'analista ti lascia un rapporto di quaranta pagine sul giocatore che affronterai nella partita contro il {opp}. È tardi e domani c'è allenamento presto.",
"El analista te enseña los datos del GPS: {name}, tu mejor jugador, es el que menos corre y menos presiona de todo el equipo. Teme que el resto empiece a imitarle.":"L'analista ti mostra i dati GPS: {name}, il tuo miglior giocatore, è quello che corre e pressa meno di tutta la squadra. Teme che gli altri inizino a imitarlo.",
"El animal más tranquilo del mundo: calma total y mucha moral.":"L'animale più tranquillo del mondo: calma totale e tanto morale.",
"El anuncio es tan absurdo que se vuelve un fenómeno. Te adoran.":"Lo spot è così assurdo che diventa un fenomeno. Ti adorano.",
