"Gana el {club} al {opp} ({score}). Mesa, debatid: ¿es el mejor momento de {name}?":"Vince il {club} contro il {opp} ({score}). Tavolo, dibattete: è il miglior momento di {name}?",
"Gana el {club} {score}. Buenas noches, y que nadie se emocione, que esto es muy largo. 📻":"Vince il {club} {score}. Buonanotte, e che nessuno si esalti, che la strada è lunga. 📻",
"Gana el {club} {score}. Como presidente de mi equipo de la liga de streamers, tomo nota de todo 🦖":"Vince il {club} {score}. Da presidente della mia squadra nella lega degli streamer, prendo nota di tutto 🦖",
"Gana el {club} {score}. Delanteros enchufados, equipo feliz 9️⃣":"Vince il {club} {score}. Attaccanti accesi, squadra felice 9️⃣",
"Gana el {club} {score}. Mi equipo de Ultimate todavía está asimilándolo 💎":"Vince il {club} {score}. La mia squadra Ultimate lo sta ancora metabolizzando 💎",
"Gana el {club} {score}. Qué momento más bonito para estar en el stream 🥥":"Vince il {club} {score}. Che bel momento per essere in live 🥥",
"Gana el {club} {score}. Si lo juego yo en el FIFA pierdo 5-0, así que respeto absoluto 🎮":"Vince il {club} {score}. Se la gioco io a FIFA perdo 5-0, quindi rispetto assoluto 🎮",
"Gana el {club} {score}. Yo, como presidente de equipo de streamers, ya me veo fichando a {name} 👑":"Vince il {club} {score}. Io, da presidente di una squadra di streamer, mi vedo già a ingaggiare {name} 👑",
"Gana el {club}. Lo de {name} ya es otra cosa, amigos. Esto es grandeza, señorío. 🤍":"Vince il {club}. Quello di {name} è un'altra cosa, amici. Questa è grandezza, signorilità. 🤍",
"Gana el {club}. Sin florituras, sin drama. Pasamos página y a por el siguiente.":"Vince il {club}. Senza fronzoli, senza drammi. Voltiamo pagina e sotto con la prossima.",
"Gana en el campo del líder invicto con una mentalidad ofensiva o de presión alta.":"Vinci in casa della capolista imbattuta con una mentalità offensiva o di pressing alto.",
"Gana encerrado atrás a un rival al menos seis puntos de media mejor.":"Vinci chiuso in difesa contro un avversario più forte di almeno sei punti di valutazione.",
"Gana liga, copa y una competición continental en la misma temporada.":"Vinci campionato, coppa e una competizione continentale nella stessa stagione.",
"Gana sin encajar jugando con uno menos ante un rival claramente mejor.":"Vinci senza subire gol in inferiorità numerica contro un avversario nettamente più forte.",
