"Ganamos porque lo merecimos. Si el resultado le molesta, que lo reclame en el campo, no en las ruedas de prensa.":"Abbiamo vinto perché lo meritavamo. Se il risultato gli dà fastidio, che lo dimostri in campo, non in conferenza stampa.",
"Ganan el derbi. ¿A quién dedica la victoria?":"Vincete il derby. A chi dedichi la vittoria?",
"Ganar da la razón. Por ahora.":"Vincere ti dà ragione. Per ora.",
