"Gol de {name} y mi vecino pegando gritos. Se ha enterado hasta el gato 🐱⚽":"Gol di {name} e il mio vicino che urla. L'ha sentito pure il gatto 🐱⚽",
"Gol de {name}. Desmarque perfecto, timing perfecto. Para enseñar en las escuelas. 🎧":"Gol di {name}. Smarcamento perfetto, tempismo perfetto. Da insegnare nelle scuole calcio. 🎧",
