"Gol. Lícito… aunque media grada te pita.":"Gol. Lecito… anche se mezzo stadio ti fischia.",
"Gol. Te lanzas a celebrarlo y todo el estadio salta contigo.":"Gol. Corri a festeggiare e tutto lo stadio salta con te.",
"Golazo de {name}. Lo he visto 20 veces en bucle. Ya es mi fondo de pantalla 🖥️":"Golazo di {name}. L'ho visto 20 volte in loop. È già il mio sfondo 🖥️",
