"Golpe de autoridad. El vestuario entiende quién manda.":"Colpo d'autorità. Lo spogliatoio capisce chi comanda.",
"Golpe duro, hay que reconocerlo. A trabajar para la próxima, juntos 💪":"Colpo duro, va riconosciuto. Al lavoro per la prossima, insieme 💪",
