"Hablar con el seleccionador":"Parlare con il commissario tecnico",
"Hablar con un profesional te cambia el chip. Vuelves a sonreír en los entrenos.":"Parlare con un professionista ti cambia la testa. Torni a sorridere negli allenamenti.",
