"Hablar con él":"Parlaci",
"Hablar con él (ya hablasteis)":"Parlaci (avete già parlato)",
"Hablar con él el primer día":"Parlargli il primo giorno",
"Hablar de ello en redes al día siguiente":"Parlarne sui social il giorno dopo",
"Hablar de lo que supone para tu liga":"Parlare di cosa significa per il tuo campionato",
