"MVP indiscutible: {name}. Qué partido. Qué nivel. ¡Qué orgullo! 👏":"MVP indiscutibile: {name}. Che partita. Che livello. Che orgoglio! 👏",
"MVP {name}. Si sale su carta en sobres, abro 100 sobres en directo. Prometido 🃏":"MVP {name}. Se esce la sua carta nei pacchetti, apro 100 pacchetti in live. Promesso 🃏",
"MVP… ya, bueno, contra este rival cualquiera sería MVP.":"MVP… sì, vabbè, contro questo avversario chiunque sarebbe MVP.",
