"Media: +3 % de progresión":"Valutazione: +3 % di progressione",
"Mediapunta":"Trequartista",
"Medio país te ve cocinar paella en una isla. Fama asegurada, descanso cero.":"Mezzo paese ti guarda cucinare la paella su un'isola. Fama assicurata, riposo zero.",
"Medio vestuario se pone de su lado y el ambiente se envenena.":"Mezzo spogliatoio si schiera con lui e l'aria si fa velenosa.",
"Mediocentro":"Centrocampista centrale",
"Mediocentro defensivo":"Mediano",
