"Más rotación descansa a los cansados en los partidos menores; en los grandes siempre juegan los mejores. Los cambios salen del banquillo.":"Più turnover fa riposare gli stanchi nelle partite minori; nei big match giocano sempre i migliori. I cambi arrivano dalla panchina.",
