"Novedades":"Novità",
"Noviembre de 2002: en su vuelta al Camp Nou con el Real Madrid, Figo recibió una lluvia de objetos al sacar un córner, entre ellos una cabeza de cochinillo.":"Novembre 2002: nel ritorno al Camp Nou con il Real Madrid, Figo ricevette una pioggia di oggetti mentre batteva un calcio d'angolo, tra cui una testa di maialino.",
"Noviembre de 2005: el Santiago Bernabéu se puso en pie para aplaudir a Ronaldinho tras sus dos golazos en el 0-3 del Barcelona.":"Novembre 2005: il Santiago Bernabéu si alzò in piedi per applaudire Ronaldinho dopo i suoi due gol da cineteca nello 0-3 del Barcellona.",
"Noviembre de 2012: el Chelsea despidió a Roberto Di Matteo seis meses después de que ganara la Champions.":"Novembre 2012: il Chelsea esonerò Roberto Di Matteo sei mesi dopo la vittoria in Champions.",
"Noviembre de 2012: en el campo del Levante, el Barcelona llegó a jugar con once futbolistas formados en La Masia.":"Novembre 2012: sul campo del Levante, il Barcellona arrivò a schierare undici giocatori cresciuti nella Masia.",
"Noviembre de 2019: tras clasificar a Gales para la Eurocopa, Gareth Bale posó con una bandera que decía «Gales. Golf. Madrid. En ese orden». En el Bernabéu no gustó nada.":"Novembre 2019: dopo aver qualificato il Galles agli Europei, Gareth Bale posò con una bandiera con scritto «Wales. Golf. Madrid. In that order». Al Bernabéu non piacque per niente.",
