"Os abrís y os pillan a la contra. Ahora pitan más.":"Vi aprite e vi colpiscono in contropiede. Ora fischiano di più.",
"Os atascáis en liga con tanto cambio y la prensa se pregunta qué pasa.":"Vi impantanate in campionato con tanti cambi e la stampa si chiede cosa succeda.",
"Os castigan cada espacio. Una goleada que escuece.":"Vi puniscono in ogni spazio. Una goleada che brucia.",
"Os centráis en la liga. La asociación lo entiende, aunque no del todo.":"Vi concentrate sul campionato. L'associazione capisce, anche se non del tutto.",
"Os dais la mano en el vestuario. Aquí no ha pasado nada.":"Vi stringete la mano nello spogliatoio. Non è successo niente.",
"Os decís las cosas a la cara y salís reforzados.":"Ve le dite in faccia e ne uscite più forti.",
"Os decís las cosas a la cara. Te promete minutos pronto.":"Vi dite le cose in faccia. Ti promette minuti a breve.",
"Os decís las verdades y salís con un plan común.":"Vi dite le cose in faccia e uscite con un piano comune.",
"Os encierran y llega el empate en un balón parado.":"Vi schiacciano nella vostra area e arriva il pareggio su calcio piazzato.",
"Os entendéis: competiréis, pero sin malos rollos.":"Vi chiarite: vi farete concorrenza, ma senza rancore.",
"Os escuchan con una sonrisa y no cambia nada.":"Vi ascoltano con un sorriso e non cambia nulla.",
"Os han goleado sin piedad y la prensa ya da la eliminatoria por perdida. En la rueda de prensa te preguntan si queda alguna esperanza.":"Vi hanno travolto senza pietà e la stampa dà già il turno per perso. In conferenza stampa ti chiedono se c'è ancora speranza.",
"Os lo avisé: {club} está para enmarcar. Pero en un cuadro triste 😂":"Ve l'avevo detto: il {club} è da incorniciare. Ma in un quadro triste 😂",
"Os lo contaba hace semanas: {name} ya es del {club}. Firma hasta {year}. Cerrado. 🔵🔴":"Ve lo dicevo settimane fa: {name} è del {club}. Firma fino al {year}. Chiuso. 🔵🔴",
"Os lo dije. LO DIJE. Y todavía hay gente que defiende esto 🤷":"Ve l'avevo detto. L'AVEVO DETTO. E c'è ancora chi difende tutto questo 🤷",
"Os mudáis a un campo pequeño. La plantilla se siente de segunda.":"Vi trasferite in un campo piccolo. La squadra si sente di serie B.",
"Os pasan por encima con uno más.":"Vi schiacciano in superiorità numerica.",
"Os pillan a la contra con el equipo partido.":"Vi puniscono in contropiede con la squadra spaccata.",
"Os pillan a la contra: empate.":"Vi beccano in contropiede: pareggio.",
