"Os quedáis sin torneo y parte de la prensa os culpa.":"Saltate il torneo e parte della stampa vi dà la colpa.",
"Otra derrota ante un rival directo. ¿Es el momento de hacer cambios?":"Un'altra sconfitta contro una diretta concorrente. È il momento di cambiare?",
"Otra derrota dolorosa con tu selección y otra lluvia de críticas. En caliente, sientes que no quieres volver a ponerte esa camiseta.":"Un'altra sconfitta dolorosa con la tua nazionale e un'altra pioggia di critiche. A caldo, senti di non voler più indossare quella maglia.",
"Otra derrota. Otra vez el mismo guion. Así no hay manera 😤 #{club}":"Altra sconfitta. Sempre lo stesso copione. Così non si va da nessuna parte 😤 #{club}",
