"Prefieres un año más con los chavales.":"Preferisci un altro anno con i ragazzi.",
"Prefiero no hablar. Cualquier cosa que diga me costará una multa y mi cuenta corriente no está para bromas.":"Preferisco non parlare. Qualsiasi cosa dica mi costerà una multa e il mio conto in banca non è in vena di scherzi.",
"Prefiero que hablen mis paradas.":"Preferisco che parlino le mie parate.",
"Prefiero que me recuerden por mi nombre y por lo que gane.":"Preferisco essere ricordato per il mio nome e per quello che vincerò.",
"Pregunta con datos en la mano. ¿Qué respondes?":"Domanda con i dati alla mano. Cosa rispondi?",
"Pregunta {n} de 3":"Domanda {n} di 3",
"Pregunten a los jugadores. Yo ya les he dicho lo que tengo que decirles, y no ha sido agradable.":"Chiedete ai giocatori. Io ho già detto loro quello che dovevo dire, e non è stato piacevole.",
"Pregúnteselo a él. Yo salí a disfrutar y a mover el balón. Lo demás, que lo arreglen los de arriba.":"Chiedilo a lui. Io sono sceso in campo per divertirmi e muovere la palla. Il resto lo sistemino quelli di sopra.",
