"Publicar los datos de todos en el vestuario":"Pubblicare i dati di tutti nello spogliatoio",
"Puede leerse como un apoyo político.":"Può essere letta come un appoggio politico.",
"Puede mejorar las condiciones de todos… o señalarte.":"Può migliorare le condizioni di tutti… o metterti nel mirino.",
"Puede salir bien… o perder la oportunidad.":"Può andare bene… o puoi perdere l'occasione.",
