"Soy del club hasta que la lesión me deje o hasta que ellos me echen. Mientras tanto, a trabajar con la pierna mala.":"Sono del club finché l'infortunio me lo permette o finché non mi cacciano. Nel frattempo, al lavoro con la gamba malandata.",
"Soy el primero en asumirlo. Tengo que sacar paradas que ahora no saco.":"Sono il primo ad ammetterlo. Devo fare parate che adesso non faccio.",
"Soy el que más trabaja de este vestuario. No lo digo yo, lo dice el entrenador. Pregúntenle.":"Sono quello che lavora di più in questo spogliatoio. Non lo dico io, lo dice l'allenatore. Chiedete a lui.",
"Soy entrenador. Tengo contrato, pero mañana puedo estar en la calle. Así es esto y no me asusta.":"Sono un allenatore. Ho un contratto, ma domani posso essere in mezzo a una strada. Funziona così e non mi spaventa.",
"Soy rico, guapo y un gran jugador. Por eso me tienen envidia. No es mi culpa.":"Sono ricco, bello e un grande giocatore. Per questo sono invidiosi di me. Non è colpa mia.",
"Soy un trabajador del club. Hago lo que me piden y ellos hacen lo suyo. Así de sencillo.":"Sono un dipendente del club. Faccio quello che mi chiedono e loro fanno la loro parte. Semplice così.",
