"Temp. de míster":"Stag. da mister",
"Temporada":"Stagione",
"Temporada 2015/16: el Leicester, que pagaba 5000 a 1 en las casas de apuestas, ganó la Premier League.":"Stagione 2015/16: il Leicester, quotato 5000 a 1 dai bookmaker, vinse la Premier League.",
"Temporada a temporada":"Stagione per stagione",
"Temporada en el juvenil":"Stagione con la Primavera",
"Temporada terminada":"Stagione finita",
"Temporada {n} de 3. El mercado de fichajes está cerrado para ti.":"Stagione {n} di 3. Il mercato è chiuso per te.",
"Temporada {season}":"Stagione {season}",
"Temporadas":"Stagioni",
"Temporadas anteriores":"Stagioni precedenti",
"Temporadas, títulos y premios":"Stagioni, titoli e premi",
"Temporizar":"Temporeggiare",
"Ten la guía a mano":"Tieni la guida a portata di mano",
"Tendrás que elegir otro entrenador e indemnizarle.":"Dovrai scegliere un altro allenatore e pagargli una buonuscita.",
"Tendré cuidado. El equipo me necesita en el campo, no en la grada.":"Starò attento. La squadra ha bisogno di me in campo, non in tribuna.",
"Tenemos un dosier de cada lanzador. El mérito también es del preparador de porteros.":"Abbiamo un dossier su ogni rigorista. Il merito è anche del preparatore dei portieri.",
"Tengo ganas de celebrarlo con toda la ciudad. Pero antes hay que ganar. Mientras, a descansar.":"Ho voglia di festeggiare con tutta la città. Ma prima bisogna vincere. Nel frattempo, riposo.",
"Tengo la medalla de segundo en el cajón, al lado de las otras. Un día les haré compañía con una de oro.":"Ho la medaglia d'argento nel cassetto, accanto alle altre. Un giorno gli farò compagnia con una d'oro.",
"Tengo la sensación de que, aunque cambiara el once, el resultado sería el mismo. Es cuestión de actitud, no de nombres.":"Ho la sensazione che, anche cambiando l'undici, il risultato sarebbe lo stesso. È questione di atteggiamento, non di nomi.",
"Tengo la suerte de jugar con los mejores. Me rodeo de gente que me hace mejor. Y no leo las redes.":"Ho la fortuna di giocare con i migliori. Mi circondo di gente che mi rende migliore. E non leggo i social.",
"Tengo opinión, claro. Pero no la cuento a la prensa. Se la cuento a él, en su despacho, con la puerta cerrada.":"Un'opinione ce l'ho, certo. Ma non la racconto alla stampa. La dico a lui, nel suo ufficio, a porta chiusa.",
"Tensión":"Tensione",
"Tensión competitiva":"Tensione agonistica",
"Tensión del momento: estrecha la franja ideal en penaltis y minijuegos.":"Tensione del momento: restringe la fascia ideale nei rigori e nei minigiochi.",
"Tenías razón: los números mentían y rindes a gran nivel.":"Avevi ragione: i numeri mentivano e rendi ad alto livello.",
