"Tirar mi penalti":"Tira il mio rigore",
"Tirarla tú: dibuja la trayectoria":"Calciarla tu: disegna la traiettoria",
"Tirarte a tu derecha":"Tuffarti alla tua destra",
"Tirarte a tu izquierda":"Tuffarti alla tua sinistra",
"Tirarte con lo que viste en vídeo":"Tuffarti come hai visto nei video",
"Tirarte en plancha para reírte de ti":"Tuffarti a pesce per prenderti in giro",
