"Tú decides":"Decidi tu",
"Tú decides fichajes, precios de las entradas, obras y presupuesto.":"Decidi tu mercato, prezzi dei biglietti, lavori e budget.",
"Tú decides las alineaciones. El dueño no lo olvidará.":"Le formazioni le decidi tu. Il proprietario non lo dimenticherà.",
