"Una casa de apuestas ofrece mucho dinero por llevar su logo en la camiseta. Parte de la afición y varios jugadores se oponen.":"Un'agenzia di scommesse offre un sacco di soldi per mettere il suo logo sulla maglia. Parte dei tifosi e diversi giocatori sono contrari.",
"Una casa de apuestas te ofrece mucho dinero por ser su imagen. Varias asociaciones de familias critican a los futbolistas que se prestan a esas campañas.":"Un'agenzia di scommesse ti offre molti soldi per essere il suo testimonial. Diverse associazioni di famiglie criticano i calciatori che si prestano a queste campagne.",
"Una catástrofe natural ha golpeado a tu país semanas antes de un torneo. La selección debate cómo mostrar su apoyo a las víctimas.":"Una catastrofe naturale ha colpito il tuo paese settimane prima di un torneo. La nazionale discute su come mostrare il proprio sostegno alle vittime.",
