"Una empresa te ofrece una plataforma de inteligencia artificial que analiza miles de partidos y te sugiere fichajes. Tus ojeadores temen quedarse sin trabajo.":"Un'azienda ti offre una piattaforma di intelligenza artificiale che analizza migliaia di partite e ti suggerisce acquisti. I tuoi osservatori temono di restare senza lavoro.",
"Una entrada absurda y te vas con un golpe en el tobillo. El club no está contento.":"Un'entrata assurda e te ne vai con una botta alla caviglia. Il club non è contento.",
"Una entrada fea en un rondo y acabáis cara a cara con un compañero. Los demás tienen que separaros.":"Un'entrata brutta in un rondo e vi ritrovate faccia a faccia con un compagno. Gli altri devono separarvi.",
