"Vuelves al estadio del {club} con la camiseta de su rival. Silbidos desde el calentamiento, pancartas con tu cara y te toca sacar los córners en ese lado.":"Torni allo stadio di {club} con la maglia della sua rivale. Fischi fin dal riscaldamento, striscioni con la tua faccia e tocca a te battere i corner da quel lato.",
"Vuelves antes de lo previsto y responde bien.":"Torni prima del previsto e il fisico risponde bene.",
"Vuelves antes, con riesgo de recaída.":"Torni prima, con rischio di ricaduta.",
"Vuelves antes… y la lesión se reproduce. Esta vez dejará huella.":"Torni prima… e l'infortunio si ripresenta. Stavolta lascerà il segno.",
"Vuelves con el mejor estado de forma de los últimos años.":"Torni nella miglior condizione fisica degli ultimi anni.",
"Vuelves con una molestia y el míster no está nada contento.":"Torni con un fastidio e il mister non è per niente contento.",
"Vuelves de jugar con tu selección y tu vuelo se retrasa ocho horas. Llegarás la misma mañana del partido de liga.":"Torni dagli impegni con la nazionale e il tuo volo ritarda di otto ore. Arriverai la mattina stessa della partita di campionato.",
