"WELTKLASSE! {name} gewinnt den Ballon d'Or! 🌟":"WELTKLASSE! {name} gewinnt den Ballon d'Or! 🌟",
"Well done, {name}. A deserved award, no doubt.":"Well done, {name}. A deserved award, no doubt.",
"What a career for {name}. Time to hang up the boots. Thanks for everything.":"What a career for {name}. Time to hang up the boots. Thanks for everything.",
"Y todavía había quien decía que íbamos a pelear arriba. JAJAJA 🤡":"E c'era pure chi diceva che avremmo lottato per le prime posizioni. AHAHAH 🤡",
"Y yo que pensaba que esta vez sí. Pues no. Vuelta a la misma historia de siempre.":"E io che pensavo fosse la volta buona. E invece no. Sempre la solita storia.",
"Y {n} eliminatoria más.":"E {n} altro turno.",
"Y {n} eliminatorias más.":"E altri {n} turni.",
"Ya era hora de un golpe de timón. {name} nos da esperanza 🔥":"Era ora di dare una svolta. {name} ci dà speranza 🔥",
"Ya era hora. Nunca fue tan bueno como lo pintan.":"Era ora. Non è mai stato così forte come lo dipingono.",
"Ya es hora de dejar el piso de alquiler. Tienes dos opciones en mente.":"È ora di lasciare l'appartamento in affitto. Hai due opzioni in mente.",
"Ya es jugador Clave":"Ora è un giocatore Chiave",
"Ya es oficial: para la grada, {name} es «{nick}» 🔥":"Ora è ufficiale: per la curva, {name} è «{nick}» 🔥",
"Ya está bien de {name}. Mucho titular y poco fútbol 🙄":"Basta con {name}. Tanti titoli e poco calcio 🙄",
"Ya hablará él en el campo. Yo no voy a añadir nada.":"Parlerà lui in campo. Io non aggiungo niente.",
"Ya hablasteis en este tramo.":"Avete già parlato in questa fase.",
"Ya habrá tiempo para gestos. Hoy toca competir.":"Ci sarà tempo per i gesti. Oggi si gioca per vincere.",
"Ya hay obras en marcha.":"Ci sono già lavori in corso.",
"Ya llevas {n} parados esta temporada. ¿Cuál es el truco con los penaltis?":"Hai già parato {n} in questa stagione. Qual è il trucco sui rigori?",
"Ya lo descubrirás… o no.":"Lo scoprirai… o forse no.",
"Ya lo hablaremos dentro.":"Ne parleremo dentro.",
"Ya negociasteis en este tramo.":"Avete già trattato in questa fase.",
"Ya ni me enfado, me da pena. Pena ajena de {club}.":"Ormai non mi arrabbio nemmeno, mi fa pena. Che imbarazzo, {club}.",
"Ya no está en venta":"Non è più in vendita",
"Ya no hay vuelta atrás.":"Non si torna più indietro.",
"Ya no os voy a defender más, {name}. Esto es insostenible.":"Non vi difenderò più, {name}. È insostenibile.",
"Ya se pueden callar unos cuantos. ¡{score}! 🤐":"Adesso in parecchi possono stare zitti. {score}! 🤐",
