"{score}. Hay noches en las que el fútbol te pide quedarte callado y disfrutar. Esta es una. 🎙️":"{score}. Ci sono notti in cui il calcio ti chiede di restare in silenzio e goderti lo spettacolo. Questa è una. 🎙️",
"{score}. Lo bueno es que ya no se puede jugar peor. Lo malo es que siempre se puede. 📻":"{score}. Il lato buono è che peggio di così non si può giocare. Quello cattivo è che si può sempre. 📻",
