"{score}. Mi abuela defiende mejor y tiene 87 años 👵":"{score}. Mia nonna difende meglio e ha 87 anni 👵",
"{score}. Ni fu ni fa. Un punto que sabe a poco… o a mucho, según se mire 🤷":"{score}. Né carne né pesce. Un punto che sa di poco… o di tanto, dipende 🤷",
