"{score}. Partido muy táctico, de ajedrez. Ninguno quiso arriesgar más de la cuenta. 🎧":"{score}. Partita molto tattica, a scacchi. Nessuno ha voluto rischiare più del dovuto. 🎧",
"{score}. SIN PALABRAS. Que alguien apague el estadio 🔦":"{score}. SENZA PAROLE. Qualcuno spenga lo stadio 🔦",
