"{trophy} para el {club}. Esto merece una celebración a lo grande. Con confeti 👑🎉":"{trophy} al {club}. Questo merita una festa in grande stile. Con coriandoli 👑🎉",
"{trophy} para el {club}. Hay alegrías que no caben en una narración. Esta es una de ellas. 🕊️🏆":"{trophy} al {club}. Ci sono gioie che non entrano in una telecronaca. Questa è una di quelle. 🕊️🏆",
"{trophy} para el {club}. Me equivoqué con {name}. Lo reconozco. Hoy, felicidades. Mañana, ya veremos. 🌶️":"{trophy} al {club}. Mi sono sbagliato su {name}. Lo ammetto. Oggi, congratulazioni. Domani, si vedrà. 🌶️",
"{trophy} para el {club}. Se ganan los títulos con defensa. Siempre lo he dicho. 🧤🏆":"{trophy} al {club}. I titoli si vincono con la difesa. L'ho sempre detto. 🧤🏆",
