"¡«{nick}» no perdona! {s} vuelve a marcar.":"«{nick}» non perdona! {s} segna ancora.",
"¡ÚLTIMA HORA! {name} elige «{choice}». La mesa se divide. ¿Tú qué opinas? 📊":"ULTIM'ORA! {name} sceglie «{choice}». Il tavolo si spacca. Tu che ne pensi? 📊",
"¡Última hora! {name} deja de ser entrenador. Lo veníamos avisando. 📺":"Ultim'ora! {name} non è più allenatore. Lo dicevamo da tempo. 📺",
"«Aquí decido yo». Hoy chupas banquillo.":"«Qui decido io». Oggi scaldi la panchina.",
"«Aquí está nuestra historia». La grada te lo agradece.":"«Qui c'è la nostra storia». La curva ti ringrazia.",
"«Aquí presiona todo el mundo». Te ganas una mirada fría.":"«Qui pressano tutti». Ti becchi un'occhiata gelida.",
"«Aquí se gana entrenando»":"«Qui si vince allenandosi»",
"«Aquí se viene aprendido». El jugador se hunde un poco más.":"«Qui si viene già imparati». Il giocatore affonda ancora di più.",
"«Aquí se vive del domingo». Te escuchan, pero no te creen.":"«Qui si vive della domenica». Ti ascoltano, ma non ti credono.",
"«Aquí tengo trabajo que acabar». La grada te aplaude.":"«Qui ho un lavoro da finire». La curva ti applaude.",
"«Así no vamos a ningún sitio.» {name} sigue pidiendo {ask}.":"«Così non andiamo da nessuna parte.» {name} chiede ancora {ask}.",
"«Con el club, en las buenas y en las malas.» Te conviertes en un símbolo.":"«Con il club, nella buona e nella cattiva sorte.» Diventi un simbolo.",
"«Demuestra que eres el mejor»":"«Dimostra che sei il migliore»",
"«El fútbol es de la gente». La grada corea tu nombre.":"«Il calcio è della gente». La curva canta il tuo nome.",
"«El fútbol es de la gente». Tu mensaje se convierte en bandera de la protesta.":"«Il calcio è della gente». Il tuo messaggio diventa la bandiera della protesta.",
"«El fútbol es suyo, no mío». Todo el mundo aplaude el gesto.":"«Il calcio è suo, non mio». Tutti applaudono il gesto.",
"«Ellos tienen más que perder». La calma se contagia.":"«Hanno più da perdere loro». La calma è contagiosa.",
"«Es normal querer jugar». Se acaba la polémica.":"«È normale voler giocare». Fine della polemica.",
"«Es una señal de lo lejos que puede llegar este fútbol». Tu discurso se cita en todos los medios.":"«È un segnale di quanto lontano può arrivare questo calcio». Il tuo discorso è citato da tutti i media.",
"«Estamos juntos y saldremos de esta». Mensaje de capitán.":"«Siamo uniti e ne usciremo». Parole da capitano.",
"«Estamos juntos». Quedas bien con casi todos.":"«Siamo uniti». Fai bella figura con quasi tutti.",
"«Fue el corazón». Titular del día.":"«È stato il cuore». Titolo del giorno.",
"«Gracias a cada compañero, a cada entrenador y a cada persona que alguna vez coreó mi nombre. Esto ha sido un sueño.»":"«Grazie a ogni compagno, a ogni allenatore e a ogni persona che ha cantato il mio nome. È stato un sogno.»",
"«Hay cosas que no se compran». Ganas el respeto del vestuario y de la grada.":"«Ci sono cose che non si comprano». Guadagni il rispetto dello spogliatoio e della curva.",
"«Hoy cuelgo las botas, pero no me voy del fútbol. Lo mejor está por llegar.»":"«Oggi appendo le scarpe al chiodo, ma non lascio il calcio. Il meglio deve ancora venire.»",
"«Hoy he estado mal y lo siento». La honestidad cae bien.":"«Oggi ho giocato male e mi dispiace». L'onestà piace.",
"«Los resultados llegarán». La directiva te respalda; la grada, a medias.":"«I risultati arriveranno». La dirigenza ti sostiene; gli spalti, a metà.",
"«Me voy antes de que el balón empiece a correr más que yo. Nos vemos en la grada… o en el banquillo.»":"«Me ne vado prima che il pallone inizi a correre più di me. Ci vediamo in tribuna… o in panchina.»",
"«Mi trabajo es el campo». El vestuario no se contagia.":"«Il mio lavoro è il campo». Lo spogliatoio non si lascia contagiare.",
"«Más» → «Editor de la partida»: cambia nombres, abreviaturas y colores de clubes, y nombres de ligas y copas.":"«Altro» → «Editor della partita»: cambia nomi, sigle e colori dei club, e i nomi di campionati e coppe.",
"«No se gana nada con niños»":"«Non si vince niente con i ragazzini»",
"«No se vende». El vestuario y la grada te lo agradecen.":"«Non è in vendita». Spogliatoio e curva ti ringraziano.",
"«Nuestro objetivo es otro». La directiva respira, la grada no tanto.":"«Il nostro obiettivo è un altro». La dirigenza tira un sospiro di sollievo, la tifoseria meno.",
"«O la estrella o nada». No hay dinero.":"«O la stella o niente». Non ci sono soldi.",
"«Partido a partido»":"«Una partita alla volta»",
"«Sal a calentar»":"«Vai a scaldarti»",
"«Salid y disfrutad»":"«Uscite e divertitevi»",
"«Sangre fría»: +2 en Tiro (Colocación si eres portero) y la forma cae más despacio tras un mal partido.":"«Sangue freddo»: +2 in Tiro (Piazzamento se sei portiere) e la forma cala più lentamente dopo una brutta partita.",
"«Si nos hicieron cuatro, podemos hacer seis»":"«Se ce ne hanno fatti quattro, possiamo farne sei»",
"«Tienen derecho a quejarse». La grada te adopta y el palco se enfada.":"«Hanno il diritto di lamentarsi». La curva ti adotta e la tribuna d'onore si arrabbia.",
"«Una cosa no tiene que ver con la otra». Te quedas sin lo uno ni lo otro.":"«Una cosa non c'entra con l'altra». Resti senza né l'una né l'altra.",
"«Vamos a por la liga»":"«Puntiamo al campionato»",
"«Vengo a ganar». La grada te adopta antes de pisar el césped.":"«Sono qui per vincere». La curva ti adotta prima che tu tocchi il campo.",
"«Yo estoy para decidir partidos, no para correr». Se ofende.":"«Io sono qui per decidere le partite, non per correre». Si offende.",
"«{answer}»":"«{answer}»",
