"«{choice}». Lo que hay que ver. {name} no da una.":"«{choice}». Roba da non credere. {name} non ne azzecca una.",
"«{choice}». Se puede discutir. Pero {name} decide con argumentos, y eso no abunda. ✒️":"«{choice}». Si può discutere. Ma {name} decide con argomenti, e non è roba da tutti. ✒️",
"«{choice}»… Jajaja. Gracias, {name}, por facilitarnos el trabajo 😅":"«{choice}»… Ahahah. Grazie, {name}, per averci facilitato il lavoro 😅",
