"«{quote}» — {name}. Interesting.":"«{quote}» — {name}. Interesting.",
"«{quote}». Eso, {name}. Con un par. Así se habla 👏":"«{quote}». Così, {name}. Con gli attributi. Così si parla 👏",
"«{quote}». Frase de {name} que dejará huella en la historia del fútbol (o no) 📜":"«{quote}». Frase di {name} che lascerà il segno nella storia del calcio (o forse no) 📜",
"«{quote}». Lo ha dicho {name}. Y yo, que llevo años en esto, no lo había oído nunca así. 🌙":"«{quote}». L'ha detto {name}. E io, che faccio questo mestiere da anni, non l'avevo mai sentito dire così. 🌙",
"«{quote}». Muy bonito, {name}. Pero el fútbol se juega en la cancha, no en el micrófono. 🌶️":"«{quote}». Molto bello, {name}. Ma il calcio si gioca sul campo, non al microfono. 🌶️",
"«{quote}». Se podía haber ahorrado la rueda de prensa entera.":"«{quote}». Poteva risparmiarsi l'intera conferenza stampa.",
"«{quote}». Sin más. Hablar es fácil, ahora a demostrarlo en el campo.":"«{quote}». Punto. Parlare è facile, ora bisogna dimostrarlo in campo.",
"«{quote}». {name} ha incendiado la sala de prensa. Mañana, portadas 🔥📰":"«{quote}». {name} ha infiammato la sala stampa. Domani, prime pagine 🔥📰",
"«{quote}»: palabras de {name}. Eso mismo queríamos que dijese antes del partido 😏":"«{quote}»: parole di {name}. Proprio quello che volevamo sentirgli dire prima della partita 😏",
