"¿Cómo planteas el partido?":"Come imposti la partita?",
"¿Cómo se va a llamar?":"Come si chiamerà?",
"¿Debut de {name}? Espero que no sea un error. Tengo mis dudas, sinceramente.":"Esordio di {name}? Spero non sia un errore. Ho i miei dubbi, sinceramente.",
"¿Dejar la selección?":"Lasciare la nazionale?",
"¿Derbi? Para mí son tres puntos como otros cualquiera.":"Derby? Per me sono tre punti come gli altri.",
"¿Dividido? Si lo estuviera, lo sabría. Solo sé que tengo 25 jugadores y todos quieren jugar. Ese es el problema.":"Diviso? Se lo fosse, lo saprei. So solo che ho 25 giocatori e tutti vogliono giocare. Il problema è quello.",
"¿Dónde juega?":"Dove gioca?",
"¿En qué vais a trabajar este verano? Marcará toda la temporada.":"Su cosa lavorerete quest'estate? Segnerà tutta la stagione.",
"¿En qué vas a trabajar esta temporada? Esto es lo que te subirá al terminarla.":"Su cosa lavorerai questa stagione? Ecco cosa migliorerà alla fine.",
"¿Era el culpable {name}? Para mí, una parte. La otra está en los despachos. 🌶️":"La colpa era di {name}? Per me, in parte. L'altra parte sta negli uffici. 🌶️",
"¿Esa es su pregunta? ¿Después de noventa minutos de partido? Siguiente pregunta, por favor.":"Questa è la tua domanda? Dopo novanta minuti di partita? Prossima domanda, per favore.",
"¿Esa foto? No salgo ni de lejos bien parado. Debería haberme puesto el otro pantalón. Eso sí que me preocupa.":"Quella foto? Non ne esco bene neanche lontanamente. Avrei dovuto mettermi gli altri pantaloni. Questo sì che mi preoccupa.",
"¿Esto es un equipo de fútbol o una excursión del colegio? Perdonad, pero vaya nivel.":"Questa è una squadra di calcio o una gita scolastica? Scusate, ma che livello.",
"¿Esto es un equipo profesional? Parecía el Día del Niño en el parque.":"Questa sarebbe una squadra professionistica? Sembrava la festa dei bambini al parco.",
"¿Ha hablado con la directiva sobre su continuidad?":"Hai parlato con la dirigenza della tua permanenza?",
"¿Han oído a {name}? «{quote}». ¡Toma ya! Esta noche lo analizamos con lupa. 🔎":"Avete sentito {name}? «{quote}». Toma ya! Stasera lo analizziamo con la lente. 🔎",
"¿Hemos pagado {fee} por {name}? Dios mío, dime que es broma… 😅":"Abbiamo pagato {fee} per {name}? Dio mio, dimmi che è uno scherzo… 😅",
"¿Irte en lo más alto?":"Andartene al top?",
"¿Merecían más? Parece que tuvieron mejores ocasiones.":"Meritavate di più? Sembra che abbiate avuto occasioni migliori.",
