"¿Qué mirás, bobo? Andá pa' allá. Digo, que estoy concentrado ya en el próximo.":"Che guardi, scemo? Vai di là. Cioè, sono già concentrato sulla prossima.",
"¿Qué mirás, bobo? Andá pa' allá. Es lo que le dije al rival, no a su afición. Que quede claro.":"Che guardi, scemo? Vai di là. È quello che ho detto all'avversario, non ai suoi tifosi. Sia chiaro.",
